def ternary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid1 = left + (right - left) // 3
        mid2 = mid1 + (right - left) // 3
        mid3 = left + 2 * (right - left) // 3

        if arr[mid1] == target:
            return mid1
        elif arr[mid2] == target:
            return mid2
        elif arr[mid3] == target:
            return mid3

        if arr[mid1] < target and arr[mid2] > target:
            right = mid2 - 1
        elif arr[mid1] > target and arr[mid3] < target:
            left = mid1 + 1
        else:
            left = mid1 + 1
            right = mid3 - 1

    return -1

# Sample input
